cards.append(compact('yangzhou_successor','扬州失散子／继任者（小说匿名人物）','这个人物与前代龙天官有血缘关系，却没有进入天官门。领袖早年另一个失散的孩子，被一位在上海走单帮的扬州商人收养，商人只是喜欢孩子的相貌，并不知道他父亲是谁。天官一系搜寻竞争者时知道了这条线，铁蛋由龙天官说漏嘴而得知扬州还有一人。后来的追索使这个身世成为权力圈内的秘密，铁天音又凭父亲的旧关系和对勒曼医院的熟悉，终于与已在最高位置上的当事人见面。他本想以公开血统为条件，要求释放几个在监狱中的人，却发现自己的筹码无效。继任者承认是旧领袖的儿子，却笑说自己与父亲不同，没有对方那样的放人能力，还让来者尽管公开。铁蛋据此判断，阻止公开的是其他老人，而继任者也许反而希望秘密被说出。后一个判断仍是他人解释，不是本人的明确宣言。这个角色可以表现出高位者的自保与无奈，却不能被设成实际无辜或无所不能；身居其位与控制所有决定有差距，既是人物的处境，也是别人误算他的原因。','已知处于继任高位，承认身世但未满足铁天音放人要求；此后个人终局未详','阶段性对立者','在受约束的高位维持自身位置与可承受的选择','会见来者时辨别真实筹码，不因被揭隐私就立即退让','面对以身世要挟的要求，可承认事实并指出权限有限，使威胁失效','头衔、血缘和实际决定权必须分别判断，不把受制等同完全无责任',[ab('高层交涉','利用自身对权力安排的了解判断威胁，能在压力下维持应答','没有展示个人战斗或法术；是否能调动具体资源需要现场证据')],[ev('090',2691,2709,'扬州失散者被提及及保密'),ev('091',311,315,'商人收养的来源'),ev('091',180,244,'铁天音通过关系会见、请求失败与继任者反应')],profile='expert'))
cards.append(compact('paoge_hostile_heads','哥老会总坛敌对首领（未分名成员）','这些哥老会首领在白老大入川时面对白老大的挑衅：一个外来者独闯总坛，要求众人奉其为总堂主，双方先比武，输得急了便越过约定，依人数围攻。白老大仍然离去，使帮会丢了颜面，首领们随即安排追索，试图把他截住羞辱。后来陈天豪为幼女庆生，五名袍哥首领见到装一愿神虫的铜盒，立即联想到白老大，急奔席前询问，几乎不顾孩子和父亲的场合。陈大帅压住他们的失态，他们又从送礼金贩口中寻出新的线索。其间既有脾气急躁的恫吓，也有用帮会切口建立共同身份的问话，显示他们对声望、阶序与自己人的看重。群卡只保存其中未被明确单独分出的首领及组织对抗行为，大麻子和执掌尚书另有主卡；不能把五人的言行全部压给其中一人。后来白老大与袍哥冰释前嫌，有人称他白神仙，这种敬畏也不证明他会分身或他们受超自然控制。演绎可以让旧敌在认可勇气后改口，同时保留他们曾恃众破坏比武规则的责任。','白老大与袍哥后来和解，未具名成员各自生死不详；以有记录的人类帮会首领形态保存','阶段性对立者','维护总坛地位、帮会颜面和内部认同','依职分、切口和声势交涉，既防外来挑战也尊重被认可的本领','威信受损时可能恃众追截；对强势盟友和现实危险会退让','江湖名誉不是可以任意伤害旁人的理由，和解不等于旧事未曾发生',[ab('帮会围堵与联络','借同门、军中身份与地方关系搜寻和施压，部分成员有武术训练','依当时成员与地理条件；不自动拥有全省兵力，不复用大麻子的独门掌法')],[ev('086',2268,2308,'总坛争斗、五首领出场与追缉'),ev('086',2341,2405,'问话、畏惧蛊苗与金贩证言'),ev('087',982,1003,'尚书个体另列并有后来联络')],profile='investigator'))
cards.append(compact('chen_military_rebels','陈天豪帅府兵变者（未具名主谋与执行者）','陈天豪军中发动兵变的人没有在这段叙述中逐一留下姓名，却形成了改变白家与陈家命运的明确对立方。他们熟悉帅府守卫和陈水的枪法，预先安排二十名敢死者专门牵制警卫队长，又让三名枪手冲向大帅。陈水没有及时出现在主人身边，边花儿虽迅速反击，仍未能阻止陈天豪受致命枪伤，只能遵照托付保护年幼的陈月梅逃出。参与兵变的团长后来自己在山中遭人图财，老年面对往事仍坐立不安；此人另有金币团长主卡，不在群体中重复设一个有相同结局的人。多年后陈月兰得知父亲死于旧部反叛，出山杀了两个首恶，说明这场行动的责任没有随权力更迭消失。群卡只保存匿名主谋和执行者的共同计划，不把每个士兵都写成知道全部阴谋，也不把三名枪手的火力与二十人的包围能力算成某个单兵的固有力量。他们的行为逻辑是趁内情、兵力和时机改变权力归属，风险则是计划外的保护者、同党背叛和后来未被抹除的仇恨。','帅府兵变已发生，三名枪手遭边花儿反击，两名首恶后来被陈月兰杀死，其余人下落未详','反派','以突袭夺取权力并排除原指挥者与忠诚卫队','利用内部情报安排攻击与牵制，行动依靠具体人员和枪械','突袭受阻时可能集中火力，事败或事后追责时同党并非必然互保','兵变成功不等于个人不受伤，人数和内应只能作为现场条件',[ab('有准备的武装突袭','根据警卫能力分配牵制人员，以枪手快速攻击核心人物','需要枪弹、内情与组织配合；不能把集体人数累加为个人肉体速度或耐久')],[ev('087',543,588,'兵变安排、枪手和托孤'),ev('087',2937,2977,'陈月兰追杀两个首恶的后果')],profile='investigator'))
save(cards)
